# fn-10-i64.1 Create Rust loading module with types

Create loading module with progress types, emitter, error types, DisplaySettings, and shared Warning type.

## New File: src-tauri/src/core/loading.rs

### LoadError Type (guaranteed valid JSON)

```rust
use serde::Serialize;

#[derive(Serialize, Debug, Clone)]
#[serde(rename_all = "camelCase")]
pub struct LoadError {
    pub code: String,
    pub message: String,
    pub details: Option<String>,
}

impl LoadError {
    pub fn new(code: &str, message: impl Into<String>) -> Self {
        Self { code: code.into(), message: message.into(), details: None }
    }

    pub fn already_open() -> Self { Self::new("ALREADY_OPEN", "Project already open") }
    pub fn cancelled() -> Self { Self::new("CANCELLED", "Operation cancelled") }
    pub fn not_found(path: &str) -> Self { Self::new("NOT_FOUND", format!("File not found: {}", path)) }
    pub fn internal(message: impl Into<String>) -> Self { Self::new("INTERNAL", message) }
}

impl std::fmt::Display for LoadError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        // ALWAYS produce valid JSON
        match serde_json::to_string(self) {
            Ok(json) => write!(f, "{}", json),
            Err(_) => write!(f, "{{\"code\":\"INTERNAL\",\"message\":\"{}\"}}", 
                self.message.replace('\"', "\\\""))
        }
    }
}

impl std::error::Error for LoadError {}
```

### DisplaySettings (MUST match UI store fields exactly)

```rust
use std::collections::HashMap;

#[derive(Serialize, Deserialize, Default, Clone, Debug)]
#[serde(rename_all = "camelCase")]
pub struct DisplaySettings {
    pub show_stations: bool,
    pub show_shots: bool,
    pub show_section_names: bool,      // UI: showSectionNames
    pub show_station_labels: bool,     // UI: showStationLabels
    pub show_shot_data: bool,          // UI: showShotData
