### LoadError Type

```rust
use serde::Serialize;

#[derive(Serialize, Debug, Clone)]
#[serde(rename_all = "camelCase")]
pub struct LoadError {
    pub code: String,
    pub message: String,
    pub details: Option<String>,
}

impl LoadError {
    pub fn new(code: &str, message: impl Into<String>) -> Self {
        Self { code: code.into(), message: message.into(), details: None }
    }

    pub fn with_details(code: &str, message: impl Into<String>, details: impl Into<String>) -> Self {
        Self { code: code.into(), message: message.into(), details: Some(details.into()) }
    }

    pub fn already_open() -> Self {
        Self::new("ALREADY_OPEN", "Project already open")
    }

    pub fn cancelled() -> Self {
        Self::new("CANCELLED", "Operation cancelled")
    }

    pub fn not_found(path: &str) -> Self {
        Self::new("NOT_FOUND", format!("File not found: {}", path))
    }

    pub fn internal(message: impl Into<String>) -> Self {
        Self::new("INTERNAL", message)
    }
}

impl std::fmt::Display for LoadError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.code, self.message)
    }
}

impl std::error::Error for LoadError {}
```

### Loading Phases

```rust
#[derive(Clone, Copy, Debug, Serialize, PartialEq)]
#[serde(rename_all = "snake_case")]
pub enum LoadingPhase {
    // Open phases (8 total)
    OpeningDatabase,
    LoadingProjectData,
    LoadingSections,
    ComputingStations,
    ComputingStatistics,
    ValidatingData,
    LoadingSettings,
    Finalizing,
    // Create phases (3 total)
    CreatingDatabase,
    InitializingProject,
    SavingSettings,
}

impl LoadingPhase {
    pub fn label(&self) -> &'static str {
        match self {
            Self::OpeningDatabase => "Opening database",
            Self::LoadingProjectData => "Loading project data",
            Self::LoadingSections => "Loading sections",
            Self::ComputingStations => "Computing stations",
            Self::ComputingStatistics => "Computing statistics",
            Self::ValidatingData => "Validating data",
            Self::LoadingSettings => "Loading settings",
            Self::Finalizing => "Finalizing",
