### Error Parsing Helper (handles Tauri's string serialization)

```typescript
interface LoadError {
  code: string;
  message: string;
  details?: string;
}

function parseLoadError(e: unknown): LoadError {
  // Tauri serializes errors as strings - try parsing as JSON
  if (typeof e === 'string') {
    try {
      return JSON.parse(e) as LoadError;
    } catch {
      return { code: 'UNKNOWN', message: e };
    }
  }
  // Already an object
  if (typeof e === 'object' && e !== null) {
    const obj = e as any;
    return {
      code: obj.code || 'UNKNOWN',
      message: obj.message || String(e),
      details: obj.details,
    };
  }
  return { code: 'UNKNOWN', message: String(e) };
}
