loadProject: async (path: string) => {
  const projectName = path.split('/').pop()?.replace(/\.(cvproj|cvchef)$/, '') ?? 'Project';
  const loadingId = get().startLoading(projectName, path);

  try {
    const result = await invoke<LoadProjectResult>('load_project_full', { path });

    // Check loadingId hasn't changed (cancelled/new load started)
    if (get().loading.loadingId !== loadingId) {
      return { success: false, message: 'Cancelled' };
    }

    if (result.success) {
      set({
        project: result.data.project,
        stations: result.data.stations,
        stats: result.data.stats,
        warnings: result.data.warnings,
        isDirty: false,
      });
      get().resetLoading();
      return result;
    } else {
      get().setLoadingError(result.message || 'Failed to load project');
      return result;
    }
  } catch (e) {
    if (get().loading.loadingId === loadingId) {
      get().setLoadingError('Unexpected error', String(e));
    }
    return { success: false, message: String(e) };
  }
},
