import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import { LoadingProgress } from '../LoadingProgress';

describe('LoadingProgress', () => {
  const defaultProps = {
    title: 'Loading Test Project...',
    phase: 'Loading survey data...',
    overallProgress: 45,
  };

  it('renders title and phase', () => {
    render(<LoadingProgress {...defaultProps} />);
    expect(screen.getByText('Loading Test Project...')).toBeInTheDocument();
    expect(screen.getByText('Loading survey data...')).toBeInTheDocument();
  });

  it('shows overall progress percentage', () => {
    render(<LoadingProgress {...defaultProps} />);
    expect(screen.getByText('45%')).toBeInTheDocument();
  });

  it('shows item counts when provided', () => {
    render(<LoadingProgress {...defaultProps} phaseCurrent={23} phaseTotal={50} />);
    expect(screen.getByText('23/50')).toBeInTheDocument();
  });

  it('shows indeterminate state when phaseProgress undefined', () => {
    render(<LoadingProgress {...defaultProps} />);
    // Indeterminate bar should have animation class
    const bar = document.querySelector('[class*="animate"]');
    expect(bar).toBeInTheDocument();
  });

  it('shows determinate progress bar when phaseProgress provided', () => {
    render(<LoadingProgress {...defaultProps} phaseProgress={60} />);
    // Should not have indeterminate animation
    const shimmer = document.querySelector('.animate-pulse-shimmer');
    expect(shimmer).not.toBeInTheDocument();
  });

  it('calls onCancel when cancel clicked', () => {
    const onCancel = jest.fn();
    render(<LoadingProgress {...defaultProps} onCancel={onCancel} />);
    fireEvent.click(screen.getByText('Cancel'));
    expect(onCancel).toHaveBeenCalled();
  });

  it('renders error state correctly', () => {
    render(
      <LoadingProgress 
        {...defaultProps} 
        title="Failed to Load Project"
        error={{ message: 'File not found', details: 'ENOENT: no such file' }}
        onCancel={() => {}}
      />
    );
    expect(screen.getByText('Failed to Load Project')).toBeInTheDocument();
    expect(screen.getByText('File not found')).toBeInTheDocument();
    expect(screen.getByText('Dismiss')).toBeInTheDocument();
  });

  it('shows expandable details in error state', async () => {
    render(
      <LoadingProgress 
        {...defaultProps} 
        error={{ message: 'File not found', details: 'ENOENT: no such file' }}
        onCancel={() => {}}
      />
    );
    fireEvent.click(screen.getByText(/Show details/));
    await waitFor(() => {
      expect(screen.getByText('ENOENT: no such file')).toBeVisible();
    });
  });

  it('has correct ARIA attributes for determinate progress', () => {
    render(<LoadingProgress {...defaultProps} phaseProgress={60} />);
    const progressbar = screen.getByRole('progressbar');
    expect(progressbar).toHaveAttribute('aria-valuenow');
    expect(progressbar).toHaveAttribute('aria-label');
  });

  it('omits aria-valuenow for indeterminate progress', () => {
    render(<LoadingProgress {...defaultProps} />);
    const progressbars = screen.getAllByRole('progressbar');
    // The indeterminate one should not have aria-valuenow
    const indeterminate = progressbars.find(p => !p.hasAttribute('aria-valuenow'));
    expect(indeterminate).toBeInTheDocument();
  });

  it('calls onRetry when retry clicked in error state', () => {
    const onRetry = jest.fn();
    render(
      <LoadingProgress 
        {...defaultProps} 
        error={{ message: 'Error' }}
        onRetry={onRetry}
        onCancel={() => {}}
      />
    );
    fireEvent.click(screen.getByText('Retry'));
    expect(onRetry).toHaveBeenCalled();
  });
});
